"use client";

import { memo, useCallback } from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import type { StoryNode } from "@/lib/types";

// ─── Types ────────────────────────────────────────────────────────────────────

export type StoryNodeData = StoryNode & {
  isOnActivePath: boolean;
  onNodeClick: (id: string) => void;
  onGenerateBranches: (id: string) => void;
};

// ─── Tone badge colours ───────────────────────────────────────────────────────

const TONE_COLOURS: Record<string, string> = {
  Opening:     "bg-sky-800 text-sky-200",
  Tense:       "bg-red-900 text-red-200",
  Revelatory:  "bg-purple-900 text-purple-200",
  Melancholy:  "bg-blue-900 text-blue-200",
  Hopeful:     "bg-green-900 text-green-200",
  Mysterious:  "bg-indigo-900 text-indigo-200",
  Humorous:    "bg-yellow-800 text-yellow-200",
  Dark:        "bg-gray-800 text-gray-300",
};

function toneBadgeClass(tone: string): string {
  return TONE_COLOURS[tone] ?? "bg-gray-700 text-gray-300";
}

// ─── Component ────────────────────────────────────────────────────────────────

function StoryNodeCardInner({ data }: NodeProps<StoryNodeData>) {
  const {
    id,
    text,
    tone,
    why,
    parentId,
    isOnActivePath,
    onNodeClick,
    onGenerateBranches,
  } = data;

  const handleBodyClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      onNodeClick(id);
    },
    [id, onNodeClick]
  );

  const handleGenerate = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      onGenerateBranches(id);
    },
    [id, onGenerateBranches]
  );

  const ringClass = isOnActivePath
    ? "ring-2 ring-amber-400 shadow-amber-400/20 shadow-lg"
    : "ring-1 ring-gray-700 hover:ring-gray-500";

  return (
    <>
      {/* Incoming handle — hidden on root node */}
      {parentId !== null && (
        <Handle
          type="target"
          position={Position.Top}
          className="!bg-gray-600 !w-2 !h-2 !border-0"
        />
      )}

      <div
        onClick={handleBodyClick}
        className={`
          relative flex flex-col gap-2 w-56 rounded-xl bg-gray-900 p-3
          cursor-pointer transition-all duration-150 ${ringClass}
        `}
      >
        {/* Tone badge */}
        <span
          className={`self-start rounded-full px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide ${toneBadgeClass(tone)}`}
        >
          {tone}
        </span>

        {/* Story text */}
        <p className="text-[13px] leading-relaxed text-gray-100 line-clamp-5">
          {text}
        </p>

        {/* Why rationale — hidden on root node (why is empty) */}
        {why && (
          <p className="text-[11px] text-gray-400 italic border-t border-gray-700 pt-2">
            <span className="not-italic font-semibold text-gray-500">Why: </span>
            {why}
          </p>
        )}

        {/* ＋ New directions button */}
        <button
          onClick={handleGenerate}
          className="
            mt-1 self-end rounded-md bg-gray-800 px-2 py-1 text-[11px]
            font-medium text-amber-400 hover:bg-gray-700 hover:text-amber-300
            transition-colors duration-100 border border-gray-700
          "
        >
          ＋ New directions
        </button>
      </div>

      {/* Outgoing handle */}
      <Handle
        type="source"
        position={Position.Bottom}
        className="!bg-gray-600 !w-2 !h-2 !border-0"
      />
    </>
  );
}

export const StoryNodeCard = memo(StoryNodeCardInner);
export default StoryNodeCard;

"use client";

import { useCallback, useEffect, useMemo } from "react";
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  useReactFlow,
  type Edge,
  type Node,
  type NodeTypes,
  BackgroundVariant,
} from "@xyflow/react";
import { computeLayout } from "@/lib/treeUtils";
import type { StoryNode } from "@/lib/types";
import { StoryNodeCard, type StoryNodeData } from "./StoryNodeCard";

// ─── Types ────────────────────────────────────────────────────────────────────

interface StoryTreeProps {
  nodes: StoryNode[];
  activePathIds: string[];
  onNodeClick: (nodeId: string) => void;
  onGenerateBranches: (nodeId: string) => void;
}

// ─── Node type registry — defined outside component to be referentially stable ─

const nodeTypes: NodeTypes = {
  storyNode: StoryNodeCard,
};

// ─── Inner component that has access to useReactFlow() ───────────────────────

function StoryTreeInner({
  nodes: storyNodes,
  activePathIds,
  onNodeClick,
  onGenerateBranches,
}: StoryTreeProps) {
  const { fitView } = useReactFlow();

  const activeSet = useMemo(() => new Set(activePathIds), [activePathIds]);

  // Recompute layout whenever the node list changes.
  const layout = useMemo(() => computeLayout(storyNodes), [storyNodes]);

  // Build React Flow node descriptors.
  const rfNodes: Node<StoryNodeData>[] = useMemo(
    () =>
      storyNodes.map((sn) => ({
        id: sn.id,
        type: "storyNode",
        position: layout[sn.id] ?? { x: 0, y: 0 },
        data: {
          ...sn,
          isOnActivePath: activeSet.has(sn.id),
          onNodeClick,
          onGenerateBranches,
        },
        // Tell React Flow the card's approximate width/height so its
        // connection-line origin calculation is accurate.
        width: 224,
        height: 200,
      })),
    [storyNodes, layout, activeSet, onNodeClick, onGenerateBranches]
  );

  // Build React Flow edge descriptors.
  const rfEdges: Edge[] = useMemo(
    () =>
      storyNodes
        .filter((n) => n.parentId !== null)
        .map((n) => {
          const isActive = activeSet.has(n.id) && activeSet.has(n.parentId!);
          return {
            id: `e-${n.parentId}-${n.id}`,
            source: n.parentId!,
            target: n.id,
            type: "smoothstep",
            style: {
              stroke: isActive ? "#fbbf24" : "#4b5563",
              strokeWidth: isActive ? 2.5 : 1.5,
            },
            animated: false,
          };
        }),
    [storyNodes, activeSet]
  );

  // Fit the view whenever nodes are added so new content is always visible.
  useEffect(() => {
    if (storyNodes.length > 0) {
      // Small timeout lets React Flow finish its internal layout pass first.
      const id = setTimeout(() => fitView({ padding: 0.2, duration: 400 }), 50);
      return () => clearTimeout(id);
    }
  }, [storyNodes.length, fitView]);

  return (
    <ReactFlow
      nodes={rfNodes}
      edges={rfEdges}
      nodeTypes={nodeTypes}
      fitView
      fitViewOptions={{ padding: 0.2 }}
      minZoom={0.2}
      maxZoom={2}
      nodesDraggable={false}
      nodesConnectable={false}
      elementsSelectable={false}
      proOptions={{ hideAttribution: false }}
      className="bg-gray-950"
    >
      <Background
        variant={BackgroundVariant.Dots}
        gap={24}
        size={1}
        color="#374151"
      />
      <Controls
        className="!bg-gray-900 !border-gray-700 !shadow-none"
        showInteractive={false}
      />
      <MiniMap
        nodeColor={(n) =>
          (n.data as StoryNodeData).isOnActivePath ? "#fbbf24" : "#374151"
        }
        maskColor="rgba(3,7,18,0.7)"
        className="!bg-gray-900 !border !border-gray-700"
      />
    </ReactFlow>
  );
}

// ─── Public export — wraps inner in ReactFlowProvider ────────────────────────

import { ReactFlowProvider } from "@xyflow/react";

export default function StoryTree(props: StoryTreeProps) {
  return (
    <div className="h-full w-full">
      <ReactFlowProvider>
        <StoryTreeInner {...props} />
      </ReactFlowProvider>
    </div>
  );
}

